script:
(function () {
  'use strict';
  // Roth IRA conversion: the tax cost now and what each choice leaves after tax later.
  //   Tax now: federal = tax(taxable income + taxable part of the conversion) - tax(taxable income),
  //     using the 2026 ordinary brackets (a conversion is ordinary income); state = flat rate x taxable part.
  //   Taxable part = amount converted - after-tax (nondeductible) basis in it.
  //   Paying the tax out of the conversion: the withheld amount is not converted, and before age 59 1/2
  //     it also costs the 10% additional tax (IRC 72(t)), taken from the converted amount too.
  //   Convert:      Roth value = amount that reaches the Roth x (1 + r)^n, tax-free when withdrawn.
  //   Don't convert: traditional IRA = amount x (1 + r)^n, less tax at the retirement rate on everything
  //                 above the basis; if the tax would have been paid from savings, that money stays
  //                 invested in a taxable account growing at r x (1 - tax rate on returns).
  //   Break-even retirement rate: the rate at which both choices leave the same amount (linear, solved directly).
  // Checked in Node (fake DOM, whole script): single, $80,000 taxable income + $50,000 conversion ->
  //   federal $11,486 ($25,700 at 22% + $24,300 at 24%); MFJ $0 income + $24,800 conversion -> $2,480
  //   (10% band); $10,000 conversion with $4,000 basis -> $6,000 taxable; $100,000 at 6% for 20 years =
  //   $320,714; single $100,000 conversion on $0 income -> $16,712 tax and, paid from savings with untaxed
  //   returns, a break-even retirement rate of 16.7% = the effective conversion rate (textbook result);
  //   paid from the IRA at 45 -> $1,671 additional tax and $81,617 reaching the Roth.
  //
  // ---- 2026 FEDERAL INCOME TAX BRACKETS (tax year 2026) ---------------------------------------------
  // IRS Rev. Proc. 2025-32, section 4.01 (as amended by P.L. 119-21). Upper limit of each band;
  // rates 10, 12, 22, 24, 32, 35, 37%. Same table as income-tax-calculator.
  var TAX_YEAR = 2026;
  var BRACKETS = {
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var EARLY_TAX = 0.10, EARLY_AGE = 59.5; // IRC 72(t) additional tax before age 59 1/2
  // ------------------------------------------------------------------------------------------------

  function tax(income, status) {
    var b = BRACKETS[status], t = 0, lower = 0;
    for (var k = 0; k < RATES.length; k++) {
      var upper = k < b.length ? b[k] : Infinity;
      if (income > lower) t += (Math.min(income, upper) - lower) * RATES[k];
      lower = upper;
    }
    return t;
  }
  function bandIndex(income, status) { // band the next dollar of income falls in
    var b = BRACKETS[status];
    for (var k = 0; k < b.length; k++) if (income < b[k]) return k;
    return b.length;
  }

  // p: amount, basis, income, status, stateRate, age, years, rate, retireRate, investTax (decimals),
  //    fromIra (bool).
  function compute(p) {
    var taxable = Math.max(0, p.amount - p.basis);
    var fed = tax(p.income + taxable, p.status) - tax(p.income, p.status);
    var state = taxable * p.stateRate;
    var total = fed + state;
    var penalty = 0, converted = p.amount, outside = total;
    if (p.fromIra) {
      outside = 0;
      if (p.age < EARLY_AGE) penalty = Math.min(total, p.amount) * EARLY_TAX * (p.amount > 0 ? taxable / p.amount : 0);
      converted = Math.max(0, p.amount - total - penalty);
    }
    var sideRate = p.rate * (1 - p.investTax), rows = [], roth = converted, ira = p.amount, side = outside, trad = 0;
    for (var y = 0; y <= p.years; y++) {
      if (y > 0) { roth *= 1 + p.rate; ira *= 1 + p.rate; side *= 1 + sideRate; }
      trad = ira - Math.max(0, ira - p.basis) * p.retireRate;
      rows.push({ year: y, age: p.age + y, roth: roth, trad: trad, side: side, diff: roth - trad - side });
    }
    var grownTaxable = Math.max(0, ira - p.basis);
    var breakEven = grownTaxable > 0 ? (ira + side - roth) / grownTaxable : NaN;
    return { taxable: taxable, fed: fed, state: state, total: total, penalty: penalty, converted: converted,
             outside: outside, roth: roth, trad: trad, side: side, diff: roth - trad - side, breakEven: breakEven,
             rows: rows, marginalBefore: RATES[bandIndex(p.income, p.status)],
             marginalTop: taxable > 0 ? RATES[bandIndex(p.income + taxable - 0.01, p.status)] : RATES[bandIndex(p.income, p.status)],
             room: bandIndex(p.income, p.status) < BRACKETS[p.status].length ? BRACKETS[p.status][bandIndex(p.income, p.status)] - p.income : Infinity };
  }

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmt(x) { return money.format(Math.abs(x) < 0.5 ? 0 : x); }
  function pct(x) { return (Math.round(x * 1000) / 10) + '%'; }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, t) { document.getElementById(id).textContent = t; }

  function update() {
    var amount = num('rcAmount'), basis = num('rcBasis'), income = num('rcIncome'), stateRate = num('rcState'),
        age = num('rcAge'), retireAge = num('rcRetireAge'), rate = num('rcRate'), retireRate = num('rcRetireRate'),
        investTax = num('rcInvestTax'), status = document.getElementById('rcStatus').value,
        fromIra = document.getElementById('rcPayFrom').value === 'ira';
    var error = document.getElementById('rcError');
    var bad = [amount, basis, income, stateRate, age, retireAge, rate, retireRate, investTax].some(isNaN) ||
              amount <= 0 || basis < 0 || basis > amount || income < 0 || stateRate < 0 || stateRate > 20 ||
              age < 18 || age > 100 || retireAge < age || retireAge > 110 || retireAge - age > 80 ||
              rate < -20 || rate > 30 || retireRate < 0 || retireRate > 70 || investTax < 0 || investTax > 70;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter an amount above $0, a basis no larger than that amount, non-negative income, a state rate up to 20%, ' +
                          'ages from 18 with the withdrawal age not below your age, a return from -20 to 30% and tax rates up to 70%.';
      return;
    }
    var r = compute({ amount: amount, basis: basis, income: income, status: status, stateRate: stateRate / 100,
                      age: age, years: Math.round(retireAge - age), rate: rate / 100, retireRate: retireRate / 100,
                      investTax: investTax / 100, fromIra: fromIra });
    set('rcTaxTotal', fmt(r.total + r.penalty));
    set('rcFed', fmt(r.fed));
    set('rcStateTax', fmt(r.state));
    set('rcPenalty', fmt(r.penalty));
    document.getElementById('rcPenaltyRow').hidden = !(r.penalty > 0);
    set('rcTaxable', fmt(r.taxable));
    set('rcEffective', r.taxable > 0 ? pct((r.total + r.penalty) / r.taxable) : '0%');
    set('rcBrackets', pct(r.marginalBefore) + (r.marginalTop !== r.marginalBefore ? ' rising to ' + pct(r.marginalTop) : ''));
    set('rcRoom', isFinite(r.room) ? fmt(r.room) + ' before the ' + pct(RATES[bandIndex(income, status) + 1]) + ' bracket' : 'Already in the top bracket');
    set('rcConverted', fmt(r.converted));
    set('rcRoth', fmt(r.roth));
    set('rcNoConvert', fmt(r.trad + r.side));
    set('rcAgeLabel', 'At age ' + Math.round(retireAge) + ', after tax');
    set('rcDiff', (r.diff >= 0 ? 'Converting: +' : 'Not converting: +') + fmt(Math.abs(r.diff)));
    set('rcBreakEven', isFinite(r.breakEven) ? (r.breakEven < 0 ? 'Below 0% (converting comes out behind at any rate)' :
        'Converting wins if your retirement tax rate is above ' + pct(r.breakEven)) : 'No taxable amount');
    var early = document.getElementById('rcEarly');
    early.hidden = !(fromIra && age < EARLY_AGE);
    var body = document.getElementById('rcSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.age, fmt(row.roth), fmt(row.trad), fmt(row.side), fmt(row.trad + row.side), fmt(row.diff)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('rcForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
